 ['Musik & hadiah',[['music','Pilihan musik','select','bamboo:Bamboo Reverie — original|piano:Ivory Piano — original|ambient:Golden Ambient — original|custom:Lagu sendiri|off:Tanpa musik'],['volume','Volume musik (0–1)','number'],['musicUrl','URL musik HTTPS','url','full'],['giftBank','Bank / e-wallet (opsional)','text'],['giftNumber','Nomor rekening','text'],['giftName','Nama pemilik rekening','text','full']]]
