async function setupTurnstile(){const root=$('#turnstile');if(!root||turnstileWidget!==undefined)return;try{const cfg=await fetch('/api/config').then(r=>r.json());if(!cfg.siteKey)throw new Error();const render=()=>{if(!root.isConnected)return;turnstileWidget=window.turnstile.render(root,{sitekey:cfg.siteKey,callback:value=>token=value,'expired-callback':()=>token='','error-callback':()=>token=''});};if(window.turnstile)render();else{const script=document.createElement('script');script.src='https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit';script.onload=render;script.onerror=()=>$('#rsvpStatus').textContent='Verifikasi RSVP belum tersedia. Hubungi pasangan melalui WhatsApp.';document.head.append(script);}}catch{$('#rsvpStatus').textContent='RSVP online belum tersedia. Hubungi pasangan melalui WhatsApp.';}}
async function submitRsvp(e){e.preventDefault();const status=$('#rsvpStatus');if(!isPublic){status.textContent='Preview berhasil dicoba. Konfirmasi ini tidak dikirim atau disimpan sebagai RSVP nyata.';return;}if(!token){status.textContent='Selesaikan verifikasi keamanan terlebih dahulu.';return;}const button=e.target.querySelector('button');button.disabled=true;status.textContent='Mengirim konfirmasi...';try{const data=Object.fromEntries(new FormData(e.target));data.guests=Number(data.guests);data.turnstileToken=token;data.id=rsvpId;const res=await fetch('/api/rsvp/'+encodeURIComponent(currentSlug),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const result=await res.json();if(!res.ok)throw new Error(result.error||'RSVP belum terkirim.');status.textContent='Terima kasih. Konfirmasi Anda sudah diterima.';e.target.reset();rsvpId=crypto.randomUUID();}catch(err){status.textContent=err.message||'RSVP belum terkirim. Silakan coba lagi.';}finally{button.disabled=false;token='';if(window.turnstile&&turnstileWidget!==undefined)window.turnstile.reset(turnstileWidget);}}
$('#closeLightbox').onclick=closeLightbox;$('#lightbox').addEventListener('close',()=>clearInterval(slideTimer));$('#prevPhoto').onclick=()=>{clearInterval(slideTimer);movePhoto(-1);};$('#nextPhoto').onclick=()=>{clearInterval(slideTimer);movePhoto(1);};document.addEventListener('keydown',e=>{if($('#lightbox').open){if(e.key==='ArrowLeft')movePhoto(-1);if(e.key==='ArrowRight')movePhoto(1);}});
$('#closeEditor').onclick=()=>$('#editor').close();$('#editor').addEventListener('close',()=>{Music.stop();$('#adminToken').value='';});['#editTop','#editFeature','#editBottom'].forEach(id=>$(id).onclick=openEditor);$('#viewHero').onclick=()=>showInvitation({...draft,theme:'royal'});$$('[data-preview]').forEach(el=>el.onclick=()=>showInvitation({...draft,theme:el.dataset.preview}));
$('#editorForm').onsubmit=async e=>{e.preventDefault();try{const events=readEvents();if(!events.length||events.some(v=>!v.title||!v.time))throw new Error('Lengkapi judul dan waktu setiap acara.');draft=formValues();draft.events=events;const errors=validateInvitation(draft);if(errors.length)throw new Error(errors.join(' '));draft=normalize(draft);try{await saveDraft();}catch{toast('Draft belum tersimpan di browser. Gunakan Ekspor draft.');}$('#editor').close();showInvitation(draft);}catch(err){$('#editorError').textContent=err.message;}};
$('#exportJson').onclick=()=>{const d=formValues();download(JSON.stringify(d,null,2),d.slug+'-draft.json','application/json');toast('Draft diekspor. Simpan file ini sebagai cadangan.');};
$('#importJson').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>60*1024*1024)throw new Error('File draft maksimal 60 MB.');draft=normalize(JSON.parse(await f.text()));await saveDraft();$('#editor').close();openEditor();toast('Draft berhasil dimuat.');}catch{toast('Draft tidak valid atau tidak dapat disimpan.');}};
$('#resetDraft').onclick=async()=>{draft=normalize(defaults);await saveDraft().catch(()=>{});$('#editor').close();openEditor();toast('Contoh undangan dipulihkan.');};
async function uploadMedia(url,secret){if(!url||url.startsWith('https:'))return url;const file=await fetch(url).then(r=>r.blob());const res=await fetch('/api/media/',{method:'POST',headers:{Authorization:'Bearer '+secret,'Content-Type':file.type},body:file});const data=await res.json();if(!res.ok)throw new Error(data.error||'Upload media gagal.');return data.url;}
$('#publish').onclick=async()=>{const button=$('#publish'),status=$('#publishResult');try{const d=formValues();const errors=validateInvitation(d);if(errors.length)throw new Error(errors.join(' '));if(d.events.some(e=>!e.title||!e.time))throw new Error('Lengkapi judul dan waktu setiap acara.');const secret=$('#adminToken').value;if(secret.length<32)throw new Error('Isi token admin Cloudflare minimal 32 karakter.');button.disabled=true;status.textContent='Memeriksa koneksi...';let config;try{const res=await fetch('/api/config');config=await res.json();}catch{throw new Error('Project ini belum terhubung ke API Cloudflare. Ikuti panduan deployment pada repo.');}if(!config.configured)throw new Error('Database undangan belum dikonfigurasi.');status.textContent='Mengunggah foto dan musik...';d.hero=await uploadMedia(d.hero,secret);for(let i=0;i<d.gallery.length;i++)d.gallery[i]=await uploadMedia(d.gallery[i],secret);if(d.music==='custom')d.musicUrl=await uploadMedia(d.musicUrl,secret);const publishedErrors=validateInvitation(d,{published:true});if(publishedErrors.length)throw new Error(publishedErrors.join(' '));status.textContent='Menerbitkan undangan...';const res=await fetch('/api/invitations/'+encodeURIComponent(d.slug),{method:'PUT',headers:{'Content-Type':'application/json',Authorization:'Bearer '+secret},body:JSON.stringify(d)});const data=await res.json();if(!res.ok)throw new Error(data.error||'Publikasi gagal.');draft=d;await saveDraft().catch(()=>{});status.textContent='Terbit: '+data.url;const a=document.createElement('a');a.href=data.url;a.textContent=' Buka undangan ↗';a.target='_blank';a.rel='noopener';status.append(a);toast('Undangan berhasil diterbitkan.');}catch(err){status.textContent=err.message;}finally{button.disabled=false;}};
$('#exportRsvp').onclick=async()=>{try{const d=formValues(),secret=$('#adminToken').value;if(secret.length<32)throw new Error('Isi token admin terlebih dahulu.');const res=await fetch('/api/rsvp/'+encodeURIComponent(d.slug),{headers:{Authorization:'Bearer '+secret}});let data;try{data=await res.json();}catch{throw new Error('API RSVP belum terhubung.');}if(!res.ok)throw new Error(data.error);const quote=x=>'"'+String(x??'').replace(/^[=+@-]/,"'").replace(/"/g,'""')+'"';const csv=[['Nama','Kehadiran','Jumlah tamu','Ucapan','Tanggal'],...data.items.map(x=>[x.name,x.attendance,x.guests,x.message,x.created_at])].map(r=>r.map(quote).join(',')).join('\r\n');download('\ufeff'+csv,d.slug+'-rsvp.csv','text/csv;charset=utf-8');}catch(err){$('#publishResult').textContent=err.message;}};
document.addEventListener('visibilitychange',()=>{if(document.hidden)Music.stop();});window.addEventListener('pagehide',()=>Music.stop());
await loadDraft();
const path=location.pathname.replace(/^\/|\/$/g,'');if(path&&path!=='index.html'){currentSlug=path;try{const res=await fetch('/api/invitations/'+encodeURIComponent(path));if(!res.ok)throw new Error();showInvitation(await res.json(),true);}catch{$('#studio').hidden=true;$('#invitation').hidden=false;$('#invitation').innerHTML='<section class="invite-cover theme-royal"><img src="/assets/flower.svg" width="40" alt=""><h1>Undangan belum tersedia.</h1><p>Periksa kembali alamat atau hubungi pengirim undangan.</p><a class="button dark" href="/" style="margin-top:25px">Kembali ke koleksi</a></section>';}}else if(new URLSearchParams(location.search).has('preview')){const theme=new URLSearchParams(location.search).get('preview');showInvitation({...draft,theme});}
